{
  "findings": [
    {
      "check_id": "CKV_GCP_1",
      "title": "Unrestricted ingress from 0.0.0.0/0",
      "resource": "google_compute_firewall.allow_http",
      "severity": "HIGH",
      "explanation": "The firewall rule allows unrestricted ingress traffic from any IP address (0.0.0.0/0) on ports 80 and 443. This exposes the system to potential attacks from the internet. Restricting the source IP range to known trusted IPs reduces the attack surface."
    }
  ],
  "patched_code": "resource \"google_compute_firewall\" \"allow_http\" {\n  name    = \"digital-library-content-management-platform-firewall-http\"\n  network = google_compute_network.digital_library_vpc.name\n  allow {\n    protocol = \"tcp\"\n    ports    = [\"80\", \"443\"]\n  }\n  source_ranges = [\"192.168.1.0/24\"] # Replace with your trusted IP range\n  target_tags   = [\"http-server\"]\n}",
  "fix_summary": "Restricted the source_ranges from 0.0.0.0/0 to a placeholder trusted IP range (192.168.1.0/24). This reduces the risk of unauthorized access from the internet."
}
